 "content": "def transform(grid):
    # Slide each non-background object rightward until it reaches the edge or another object.
    h, w = len(grid), len(grid[0])
    cells = {}
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            obj = []
            while stack:
                y, x = stack.pop()
                obj.append((y, x, color))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p); stack.append(p)
            cells[(r,c)] = obj
    out = [[0]*w for _ in range(h)]
    # Process objects bottom-right first; each preserves shape and slides right maximally.
    objects = list(cells.values())
    objects.sort(key=lambda o: max(y for y,x,v in o), reverse=True)
    for obj in objects:
        shift = 0
        while True:
            if any(x+shift+1 >= w or out[y][x+shift+1] != 0 for y,x,v in obj):
                break
            shift += 1
        for y,x,v in obj:
            out[y][x+shift] = v
    return out

